pub struct Interval {
    pub min: f64,
    pub max: f64,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Constructs a Chebyshev polynomial descriptor from an input vector of i8 coefficients.
/// 
/// # Panics
///
/// Panics if `coef` is empty (we require a non‐empty list of coefficients).
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Ensure the coefficient list is non‐empty
    assert!(!coef.is_empty(), "Coefficient list must be non‐empty");

    // Convert coefficients from i8 to i32
    let coef_i32: Vec<i32> = coef.into_iter()
                                 .map(|c| c as i32)
                                 .collect();

    // Default domain and window intervals [-1, 1]
    let interval = Interval { min: -1.0, max: 1.0 };

    ChebyshevPoly {
        coef: coef_i32,
        domain: interval.clone(),
        window: interval,
    }
}

